use std::fmt::Write;

use crabrouter_model::RouterConfig;

/// Renders `igmpproxy.conf` for IPTV multicast forwarding between upstream WAN/VLAN and LANs.
pub fn render_igmpproxy_conf(cfg: &RouterConfig) -> String {
    if !cfg.iptv.enabled {
        return "# IPTV multicast proxy is disabled\n".to_string();
    }

    let upstream = cfg.iptv.upstream_interface.trim();
    let downstream = resolve_downstream_interfaces(cfg);

    let mut out = String::from(
        "# Generated by crabrouterd — do not edit manually\n\
         quickleave\n\n",
    );
    if !upstream.is_empty() {
        let _ = writeln!(out, "phyint {upstream} upstream ratelimit 0 threshold 1");
        for cidr in &cfg.iptv.altnet_cidrs {
            let trimmed = cidr.trim();
            if !trimmed.is_empty() {
                let _ = writeln!(out, "    altnet {trimmed}");
            }
        }
        out.push('\n');
    }

    for iface in &downstream {
        let _ = writeln!(out, "phyint {iface} downstream ratelimit 0 threshold 1");
    }
    out
}

/// Renders `/run/crabrouter/udpxy.env` consumed by `udpxy.service`.
pub fn render_udpxy_env(cfg: &RouterConfig) -> String {
    if !cfg.iptv.enabled || !cfg.iptv.udpxy_enabled {
        return "UDPXY_OPTS=\"\"\n".to_string();
    }
    let upstream = cfg.iptv.upstream_interface.trim();
    let downstream = resolve_downstream_interfaces(cfg);
    let listen_if = downstream.first().map_or("br-lan", String::as_str);
    let mut opts = format!(
        "-p {} -a {} -c {}",
        cfg.iptv.udpxy_port, listen_if, cfg.iptv.udpxy_max_clients
    );
    if !upstream.is_empty() {
        let _ = write!(opts, " -m {upstream}");
    }
    format!("# Generated by crabrouterd — do not edit manually\nUDPXY_OPTS=\"{opts}\"\n")
}

fn resolve_downstream_interfaces(cfg: &RouterConfig) -> Vec<String> {
    if !cfg.iptv.downstream_interfaces.is_empty() {
        return cfg
            .iptv
            .downstream_interfaces
            .iter()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
    }
    cfg.lans.iter().map(|l| l.bridge.clone()).collect()
}

#[cfg(test)]
mod tests {
    use super::{render_igmpproxy_conf, render_udpxy_env};
    use crabrouter_model::RouterConfig;

    #[test]
    fn renders_igmpproxy_and_udpxy_when_enabled() {
        let mut cfg = RouterConfig::default();
        cfg.iptv.enabled = true;
        cfg.iptv.upstream_interface = "eth0.85".to_string();
        cfg.iptv.udpxy_enabled = true;
        cfg.iptv.udpxy_port = 4022;

        let igmp = render_igmpproxy_conf(&cfg);
        assert!(igmp.contains("phyint eth0.85 upstream"));
        assert!(igmp.contains("phyint br-lan downstream"));

        let udpxy = render_udpxy_env(&cfg);
        assert!(udpxy.contains("-p 4022 -a br-lan -c 16 -m eth0.85"));
    }
}
